questions.solution:
def privatized_histogram(values, n_blocks, block_size, bins):
    """histShared on the CPU: return (hist, merges), the merged histogram and the number of global merge atomics.
    Element i belongs to thread i % (n_blocks * block_size), as in a grid-stride loop."""
    stride = n_blocks * block_size
    hist = [0] * bins
    merges = 0
    for b in range(n_blocks):
        private = [0] * bins                       # phase 1: every block starts from zero
        for i, v in enumerate(values):
            if (i % stride) // block_size == b:
                private[v] += 1                    # count in the block's private histogram
        for k in range(bins):
            hist[k] += private[k]                  # merge: one global atomic per bin per block
            merges += 1
    return hist, merges
